from django.db import migrations, models

import services.comisiones.models

# Los bonos por meta de la politica, por estado. «Mas de 50» se lee desde 50:
# los tramos van de 40 a 49 y el siguiente empieza donde termina ese.
BONOS_POLITICA = {
    "aragua": [(15, 50), (20, 80), (30, 120), (40, 200), (50, 250)],
    "carabobo": [(30, 120), (40, 200), (50, 250)],
}


def sembrar_bonos(apps, schema_editor):
    """Pone los bonos de la politica si las condiciones no tienen ninguno.

    Los estados se buscan por nombre: el que no este en el catalogo se salta, y
    se puede anadir despues desde Comisiones › Condiciones.
    """
    Condiciones = apps.get_model("comisiones", "CondicionesComision")
    Estado = apps.get_model("subscriptions", "Estado")
    condiciones, _ = Condiciones.objects.get_or_create(pk=1)
    if condiciones.bonos_meta:
        return
    bonos = []
    for estado in Estado.objects.all():
        tramos = BONOS_POLITICA.get(estado.nombre.strip().lower())
        if tramos:
            bonos.append({
                "estado_id": estado.id,
                "tramos": [{"desde": desde, "monto": float(monto)} for desde, monto in tramos],
            })
    condiciones.bonos_meta = bonos
    condiciones.save(update_fields=["bonos_meta"])


class Migration(migrations.Migration):

    dependencies = [
        ('comisiones', '0008_cierres_archivados'),
        ('subscriptions', '0009_plan_comision_pyme_pct'),
    ]

    operations = [
        migrations.AddField(
            model_name='condicionescomision',
            name='bonos_meta',
            field=models.JSONField(default=services.comisiones.models._bonos_meta),
        ),
        migrations.RunPython(sembrar_bonos, migrations.RunPython.noop),
    ]
